public class WeightedSpinnerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static int sum(int[] a) {
        int s = 0;
        for (int v : a) {
            s += v;
        }
        return s;
    }

    public static void main(String[] args) {
        String[] labels = {"red", "green", "blue"};
        int[] weights = {1, 3, 6};

        try {
            check("pick from a one-label table", "only",
                    WeightedSpinner.pick(new String[]{"only"}, new int[]{4}, new java.util.Random(1L)));

            java.util.Random rng = new java.util.Random(42L);
            String seq = WeightedSpinner.pick(labels, weights, rng) + ","
                    + WeightedSpinner.pick(labels, weights, rng) + ","
                    + WeightedSpinner.pick(labels, weights, rng) + ","
                    + WeightedSpinner.pick(labels, weights, rng);
            check("four picks sharing one Random(42)", "red,green,blue,blue", seq);

            check("tally(seed 7, 1000 draws)", "[90, 302, 608]",
                    java.util.Arrays.toString(WeightedSpinner.tally(labels, weights, 7L, 1000)));

            check("tally(seed 42, 20 draws)", "[3, 7, 10]",
                    java.util.Arrays.toString(WeightedSpinner.tally(labels, weights, 42L, 20)));

            check("a weight of 0 never wins", "[0, 48, 52]",
                    java.util.Arrays.toString(WeightedSpinner.tally(
                            new String[]{"a", "b", "c"}, new int[]{0, 5, 5}, 3L, 100)));

            check("counts add up to the number of draws", 1000,
                    sum(WeightedSpinner.tally(labels, weights, 7L, 1000)));

            check("same seed gives the same tally",
                    java.util.Arrays.toString(WeightedSpinner.tally(labels, weights, 7L, 50)),
                    java.util.Arrays.toString(WeightedSpinner.tally(labels, weights, 7L, 50)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

