/**
 * Weighted random choice from a table of labels and whole-number weights.
 */
public class WeightedSpinner {

    public static String pick(String[] labels, int[] weights, java.util.Random rng) {
        int total = 0;
        for (int w : weights) {
            total += w;
        }
        int ticket = rng.nextInt(total);
        int running = 0;
        for (int i = 0; i < labels.length; i++) {
            running += weights[i];
            if (ticket < running) {
                return labels[i];
            }
        }
        return labels[labels.length - 1];
    }

    public static int[] tally(String[] labels, int[] weights, long seed, int draws) {
        java.util.Random rng = new java.util.Random(seed);
        int[] counts = new int[labels.length];
        for (int d = 0; d < draws; d++) {
            String chosen = pick(labels, weights, rng);
            for (int i = 0; i < labels.length; i++) {
                if (labels[i].equals(chosen)) {
                    counts[i]++;
                    break;
                }
            }
        }
        return counts;
    }
}
